SELECT 
        FROM task_assignment r
        WHERE r.user_id=#{userId}
          AND r.id=#{id}

SELECT 
        FROM task_assignment r 
        ORDER BY r.sort_order,r.idr.assigned_at DESC,r.id DESC
        LIMIT #{q.size}
        OFFSET #{q.offset}

mapper.update:
UPDATE task_assignment
        SET ended_at=#{endedAt},
            end_reason=#{endReason},
            sort_order=#{sortOrder},
            version=version+1,
            updated_at=CURRENT_TIMESTAMP
        WHERE id=#{id}
          AND user_id=#{userId}
          AND version=#{version}
          AND ended_at IS NULL

